function isVirtuaRankingSaleV97(s){const product=[s?.real_product_summary,s?.product_summary,s?.product_group_summary].map(v=>String(v||'').toUpperCase()).join(' | '),team=String(s?.team_name||s?.imperium_team_name||'').toUpperCase(),consult=String(s?.consultant_name||s?.imperium_consultant_name||s?.commercial_seller_name||'').toUpperCase();return (product.includes('VIRTUA')||product.includes('FIBRA')||product.includes('BANDA LARGA'))&&!team.includes('MDU')&&!consult.startsWith('MDU - ')}
function summarize(sales,dict){const names=Object.fromEntries(dict.profiles.map(x=>[x.user_id,x.full_name]));const teams=Object.fromEntries(dict.teams.map(x=>[x.id,x.name]));let byConsult={},byTeam={};for(const s of sales){if(!isVirtuaRankingSaleV97(s))continue;let n=names[s.consultant_id]||s.imperium_consultant_name||'Sem consultor',t=teams[s.team_id]||s.imperium_team_name||'Sem equipe';if(String(t||'').toUpperCase().includes('MDU')||String(n||'').toUpperCase().startsWith('MDU - '))continue;byConsult[n]=(byConsult[n]||0)+1;byTeam[t]=(byTeam[t]||0)+1}return {names,teams,consult:Object.entries(byConsult).sort((a,b)=>b[1]-a[1]),team:Object.entries(byTeam).sort((a,b)=>b[1]-a[1])}}
async function renderDashboard(){if(['admin','supervisor'].includes(profile.role))return renderAdminDashboard({sb,content,profile,toast,navigate,money,date,escapeHtml});setTitle('Dashboard','Produção comercial em tempo real');const [allSales,dict]=await Promise.all([visibleSales(),dictionaries()]);const selected=localStorage.getItem('tv_dashboard_city')||'',sales=allSales.filter(x=>!selected||saleCityKey(x)===selected),sm=summarize(sales,dict),approved=sales.filter(x=>['approved','sync_pending','synced'].includes(x.status)),pending=sales.filter(x=>['submitted','under_review','pending_correction'].includes(x.status)),value=sales.reduce((a,x)=>a+Number(x.total_value||0),0);content.innerHTML=`<div class="card city-filterbar"><div><b>Operação por cidade</b><span class="muted">Dados reais sincronizados do comercial</span></div><select id="dashboardCityFilter">${cityFilterOptions(selected)}</select></div><div class="hero"><div><div class="kicker">${roleLabel[profile.role]}</div><h3>Produção TechNET Vendas</h3><p>Acompanhe vendas de campo, análise do BackOffice e histórico comercial sincronizado.</p></div><div class="badge">${sales.length} vendas no período</div></div><div class="stats"><div class="stat"><div class="label">Vendas</div><div class="value">${sales.length}</div><div class="sub">Total visível no período</div></div><div class="stat"><div class="label">Aprovadas</div><div class="value">${approved.length}</div><div class="sub">Aprovadas / sincronizadas</div></div><div class="stat"><div class="label">Em análise</div><div class="value">${pending.length}</div><div class="sub">Fila operacional</div></div><div class="stat"><div class="label">Valor</div><div class="value">${money(value)}</div><div class="sub">Produção acumulada</div></div></div><div class="grid2"><div class="card"><div class="card-head"><h3>Ranking Virtua por equipe</h3><span class="muted">Somente Virtua / Banda Larga</span></div>${rankHtml(sm.team)}</div><div class="card"><div class="card-head"><h3>Consultores Virtua</h3><span class="muted">Somente Virtua / Banda Larga</span></div>${rankHtml(sm.consult)}</div></div><div class="card" style="margin-top:18px"><div class="card-head"><h3>Últimas vendas</h3><button class="ghost" id="goMap">Ver mapa</button></div>${salesTable(sales.slice(0,12),sm.names,sm.teams)}</div>`;wireSaleEditActions();applyConsultantValuePrivacy(pending.length);$('#dashboardCityFilter').onchange=e=>{localStorage.setItem('tv_dashboard_city',e.target.value);renderDashboard()};$('#goMap').onclick=()=>navigate('map')}
function applyConsultantValuePrivacy(analysisCount){if(profile?.role!=='consultant')return;const stats=content.querySelector('.stats');if(stats){stats.classList.add('consultant-stats');const cards=[...stats.children].filter(x=>x.classList?.contains('stat'));if(cards[2]&&analysisCount!=null){cards[2].querySelector('.label').textContent='Em análise';cards[2].querySelector('.value').textContent=String(analysisCount)}if(cards[3])cards[3].remove()}content.querySelectorAll('.table-wrap table').forEach(t=>{const th=[...t.querySelectorAll('thead th')];const valueIndex=th.findIndex(x=>x.textContent.trim().toLowerCase()==='valor');if(valueIndex<0)return;th[valueIndex].remove();t.querySelectorAll('tbody tr').forEach(r=>r.children[valueIndex]?.remove())})}
function rankHtml(rows){if(!rows.length)return '<div class="empty">Ainda não há produção para o período.</div>';const visible=rows.slice(0,8),peak=Math.max(1,...visible.map(r=>Number(r[1]||0)));return `<div class="rank premium-rank">${visible.map((r,i)=>{const value=Number(r[1]||0),width=Math.max(8,Math.round(value/peak*100));return `<div class="rank-item"><div class="rank-pos">${i+1}</div><div class="rank-copy"><div class="rank-name">${escapeHtml(r[0])}</div><div class="rank-track" aria-hidden="true"><i style="--rank-width:${width}%"></i></div><div class="rank-sub">${value} ${value===1?'venda Virtua':'vendas Virtua'} no período</div></div><div class="rank-score" aria-label="${value} vendas">${value}</div></div>`}).join('')}</div>`}
function imperiumStatusHtml(s){const st=String(s.imperium_submit_status||'not_ready');if(s.imperium_sale_id){const ref=s.imperium_proposal||s.imperium_contract||s.imperium_sale_id;return `<span class="pill green">Enviado ✓</span><br><small class="muted">${escapeHtml(String(ref))}</small>`}if(st==='queued')return '<span class="pill amber">Aguardando envio</span>';if(st==='sending'||st==='processing')return '<span class="pill amber">Enviando…</span>';if(st==='error'||st==='failed')return '<span class="pill red">Erro no envio</span>';return '<span class="pill">Não enviado</span>'}
function saleEditAction(s){if(!['draft','pending_correction'].includes(String(s?.status||''))||!['consultant','supervisor','admin'].includes(profile?.role))return '';const label=s.status==='pending_correction'?'Corrigir venda':'Editar rascunho';return `<button type="button" class="ghost sale-edit" data-id="${escapeHtml(s.id)}">${label}</button>`}
