function salesTable(rows,names={},teams={}){if(!rows.length)return `<div class="empty-action">${icon('sales')}<h3>Nenhuma venda encontrada</h3><p>Amplie o período ou remova os filtros para visualizar outros registros.</p></div>`;const cards=`<div class="sales-cards">${rows.map(s=>`<article class="sales-card" data-sale-id="${escapeHtml(s.id)}"><div class="sales-card-head"><div class="sales-card-mark" aria-hidden="true">${escapeHtml(String(s.customer_name||'?').trim().charAt(0).toUpperCase()||'?')}</div><div class="sales-card-identity"><small>Cliente</small><b>${escapeHtml(s.customer_name||'Sem nome')}</b><span>${escapeHtml(s.imperium_proposal||s.customer_phone||'Sem proposta')}</span></div><div class="sales-card-state">${pill(s.status)}</div></div><div class="sales-card-meta"><span><small>Data</small><b>${date(s.sold_at||s.created_at)}</b></span><span><small>Cidade</small><b>${escapeHtml(s.city_name||'Não informada')}</b></span><span><small>Consultor</small><b>${escapeHtml(names[s.consultant_id]||s.consultant_name||s.imperium_consultant_name||'-')}</b></span><span><small>Equipe</small><b>${escapeHtml(teams[s.team_id]||s.team_name||s.imperium_team_name||'-')}</b></span></div><div class="sales-card-foot"><span class="sales-card-origin"><i></i>${s.source==='imperium'?'Sincronizada com Imperium':'Registrada no TechNET'}</span><span class="sales-imperium-status">${imperiumStatusHtml(s)}</span>${saleEditAction(s)}</div></article>`).join('')}</div>`;return `${cards}<div class="table-wrap sales-desktop"><table aria-label="Vendas do período"><thead><tr><th>Data</th><th>Cliente</th><th>Consultor</th><th>Equipe</th><th>Status</th><th>Imperium</th><th>Origem</th><th>Valor</th><th>Ação</th></tr></thead><tbody>${rows.map(s=>`<tr data-sale-id="${escapeHtml(s.id)}"><td data-label="Data">${date(s.sold_at||s.created_at)}</td><td data-label="Cliente"><b>${escapeHtml(s.customer_name||'Sem nome')}</b><br><span class="muted">${escapeHtml(s.imperium_proposal||s.customer_phone||'')}</span></td><td data-label="Consultor">${escapeHtml(names[s.consultant_id]||s.consultant_name||s.imperium_consultant_name||'-')}</td><td data-label="Equipe">${escapeHtml(teams[s.team_id]||s.team_name||s.imperium_team_name||'-')}</td><td data-label="Status">${pill(s.status)}</td><td data-label="Imperium">${imperiumStatusHtml(s)}</td><td data-label="Origem">${s.source==='imperium'?'Sincronizado':'TechNET'}</td><td data-label="Valor">${saleValueHtml(s)}</td><td data-label="Ação">${saleEditAction(s)}</td></tr>`).join('')}</tbody></table></div>`}
