async function renderSales(title){setTitle(title,title==='Minhas vendas'?'Acompanhe suas vendas':'Produção visível da equipe');const [allSales,dict]=await Promise.all([visibleSales(),dictionaries()]);const selected=localStorage.getItem('tv_sales_city')||'',nonDraft=allSales.filter(x=>x.status!=='draft'),sales=nonDraft.filter(x=>!selected||saleCityKey(x)===selected),sm=summarize(sales,dict);content.innerHTML=`<div class="card city-filterbar"><div><b>Filtrar produção</b><span class="muted">Natal, Fortaleza, Recife e Mossoró</span></div><select id="salesCityFilter">${cityFilterOptions(selected)}</select></div><div class="stats"><div class="stat"><div class="label">Vendas</div><div class="value">${sales.length}</div></div><div class="stat"><div class="label">Aprovadas</div><div class="value">${sales.filter(x=>['approved','sync_pending','synced'].includes(x.status)).length}</div></div><div class="stat"><div class="label">Pendências</div><div class="value">${sales.filter(x=>x.status==='pending_correction').length}</div></div><div class="stat"><div class="label">Produção</div><div class="value">${money(sales.reduce((a,x)=>a+Number(x.total_value||0),0))}</div></div></div><div class="card"><div class="card-head"><h3>${title}</h3><button class="primary" id="newSaleTop">Nova venda</button></div>${salesTable(sales,sm.names,sm.teams)}<div class="test-cleanup"><h4>Cadastro de teste ou incorreto</h4><p class="muted">Administradores e supervisores podem cancelar um cadastro sem apagar o histórico.</p><div class="customer-search-row"><input id="cancelSaleId" placeholder="Cole o ID da venda"><button class="danger" id="cancelSaleBtn" type="button">Cancelar cadastro</button></div></div></div>`;applyConsultantValuePrivacy(sales.filter(x=>['submitted','under_review','pending_correction'].includes(x.status)).length);$('#salesCityFilter').onchange=e=>{localStorage.setItem('tv_sales_city',e.target.value);renderSales(title)};$('#newSaleTop').onclick=()=>navigate('new-sale');const cb=$('#cancelSaleBtn');if(cb){const allowed=['admin','supervisor'].includes(profile.role);cb.disabled=!allowed;if(!allowed)cb.title='Somente administrador ou supervisor';cb.onclick=async()=>{if(!allowed)return toast('Somente administrador ou supervisor pode cancelar cadastros');const id=$('#cancelSaleId').value.trim();if(!id)return toast('Informe o ID da venda');const reason=prompt('Motivo do cancelamento (ex.: TESTE ou CADASTRO INCORRETO):');if(!reason)return;const {data:old,error:e0}=await sb.from('tv_sales').select('id,status,customer_name').eq('id',id).single();if(e0||!old)return toast('Venda não encontrada');if(['approved','sync_pending','synced'].includes(old.status))return toast('Venda aprovada/sincronizada não pode ser cancelada por esta opção');if(!confirm(`Cancelar o cadastro de ${old.customer_name||id}? O histórico será mantido.`))return;const {error}=await sb.from('tv_sales').update({status:'cancelled',notes:`${reason} | Cancelado em ${new Date().toLocaleString('pt-BR')}`}).eq('id',id);if(error)return toast(error.message);await sb.from('tv_sale_history').insert({sale_id:id,actor_id:session.user.id,from_status:old.status,to_status:'cancelled',note:`Cadastro cancelado: ${reason}`});toast('Cadastro cancelado e histórico preservado');renderSales(title)}}}
async function renderBackoffice(){setTitle('BackOffice','Fila de análise das vendas de campo');const {data,error}=await sb.from('tv_sales').select('*').in('status',['submitted','under_review','pending_correction']).order('submitted_at',{ascending:true}).limit(1000);if(error)throw error;const rows=data||[];content.innerHTML=`<div class="hero"><div><div class="kicker">BackOffice</div><h3>Fila de análise</h3><p>Analise vendas, devolva pendências e aprove para a fila de sincronização comercial.</p></div><div class="badge">${rows.length} aguardando ação</div></div><div class="card"><div class="queue">${rows.length?rows.map(s=>`<div class="sale-card"><div><h4>${s.customer_name}</h4><div class="sale-meta">${s.customer_document||'Documento não informado'} · ${s.customer_phone||'Sem telefone'}<br>${s.street||''} ${s.street_number||''} · ${s.city_name||''}/${s.state||''}<br><b>${s.product_summary||'Produto não informado'}</b> · ${money(s.total_value)} · ${pill(s.status)}</div></div><div class="actions"><button class="ghost review" data-id="${s.id}" data-status="under_review">Analisar</button><button class="danger review" data-id="${s.id}" data-status="pending_correction">Pendência</button><button class="success review" data-id="${s.id}" data-status="sync_pending">Aprovar</button></div></div>`).join(''):'<div class="empty">Nenhuma venda aguardando análise.</div>'}</div></div>`;document.querySelectorAll('.review').forEach(b=>b.onclick=async()=>{const id=b.dataset.id,to=b.dataset.status,note=to==='pending_correction'?prompt('Informe a pendência para o consultor:')||'Correção solicitada':to==='sync_pending'?'Aprovada pelo BackOffice':'Em análise';const {data:old}=await sb.from('tv_sales').select('status').eq('id',id).single();const {error}=await sb.from('tv_sales').update({status:to,backoffice_id:session.user.id,reviewed_at:new Date().toISOString()}).eq('id',id);if(error)return toast(error.message);await sb.from('tv_sale_history').insert({sale_id:id,actor_id:session.user.id,from_status:old?.status,to_status:to,note});toast('Venda atualizada');renderBackoffice()})}async function renderAdmin(){setTitle('Administração','Usuários, equipes e associação de contas comerciais');return renderAdminUsers({sb,content,toast,profile,session});}
function adminUserHtml(u,cities,teams,accounts){return `<div class="admin-user"><div><div class="kicker">${u.email||'Usuário'}</div><label>Nome<input class="u-name" value="${escapeHtml(u.full_name||'')}"></label></div><label>Perfil<select class="u-role"><option value="consultant" ${u.role==='consultant'?'selected':''}>Consultor</option><option value="supervisor" ${u.role==='supervisor'?'selected':''}>Supervisor</option><option value="backoffice" ${u.role==='backoffice'?'selected':''}>BackOffice</option><option value="admin" ${u.role==='admin'?'selected':''}>Administrador</option></select></label><label>Cidade<select class="u-city"><option value="">-</option>${cities.map(c=>`<option value="${c.id}" ${u.city_id===c.id?'selected':''}>${c.name}</option>`).join('')}</select></label><label>Equipe<select class="u-team"><option value="">-</option>${teams.map(t=>`<option value="${t.id}" ${u.team_id===t.id?'selected':''}>${t.name}</option>`).join('')}</select></label><label>Conta comercial<select class="u-imp"><option value="">Não vinculado</option>${accounts.map(a=>`<option value="${a.id}" ${u.imperium_account_id===a.id?'selected':''}>${a.base_key.toUpperCase()} · ${a.username}</option>`).join('')}</select></label><button class="primary save-user" data-id="${u.user_id}">Salvar</button></div>`}
