function setupGlobalSearch(){let host=document.getElementById('globalSearchHost');if(!host){host=document.createElement('div');host.id='globalSearchHost';host.className='global-search';host.innerHTML=`<button class="global-search-trigger" id="globalSearchTrigger" aria-label="Buscar no sistema"><span class="global-search-icon">${icon('search')}</span><b>Buscar cliente, proposta ou endereço…</b><kbd>Ctrl K</kbd></button><dialog id="globalSearchDialog" class="global-search-dialog"><div class="global-search-box"><div class="global-search-input"><span class="global-search-icon">${icon('search')}</span><input id="globalSearchInput" placeholder="Cliente, CPF, telefone, proposta, contrato, endereço…" autocomplete="off"><button id="globalSearchClose" class="ghost">${icon('close')}</button></div><div id="globalSearchResults" class="global-search-results"><div class="empty">Digite pelo menos 3 caracteres.</div></div></div></dialog>`;document.querySelector('.topbar-copy')?.after(host)}const dialog=document.getElementById('globalSearchDialog'),input=document.getElementById('globalSearchInput'),results=document.getElementById('globalSearchResults');if(dialog&&dialog.parentElement!==document.body)document.body.appendChild(dialog);let timer;const open=()=>{if(!dialog||dialog.open)return;try{dialog.showModal()}catch{dialog.setAttribute('open','')}setTimeout(()=>input?.focus(),30)},close=()=>{if(!dialog)return;if(dialog.open)dialog.close();else dialog.removeAttribute('open')};document.getElementById('globalSearchTrigger').onclick=open;document.getElementById('globalSearchClose').setAttribute('aria-label','Fechar busca');document.getElementById('globalSearchClose').onclick=close;if(!window.__tvSearchKeys){window.__tvSearchKeys=true;document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();dialog.open?close():open()}if(e.key==='Escape'&&dialog.open)close()})}input.oninput=()=>{clearTimeout(timer);const q=input.value.trim();if(q.length<3){results.innerHTML='<div class="empty">Digite pelo menos 3 caracteres.</div>';return}results.innerHTML='<div class="skeleton-list"><i></i><i></i><i></i></div>';timer=setTimeout(async()=>{try{const {data,error}=await sb.rpc('tv_global_search',{p_query:q,p_limit:20});if(error)throw error;const rows=data?.items||[];results.innerHTML=rows.length?rows.map(s=>`<button class="global-result" data-id="${s.id}"><span><b>${escapeHtml(s.customer_name||'Sem nome')}</b><small>${escapeHtml(s.imperium_proposal||s.contract_number||s.customer_phone||'')}</small></span><span><b>${escapeHtml(s.consultant_name||'')}</b><small>${escapeHtml(s.city_name||'')} · ${escapeHtml(s.team_name||'')}</small></span><span>${pill(s.status)}</span></button>`).join(''):'<div class="empty">Nenhum resultado encontrado.</div>';results.querySelectorAll('.global-result').forEach(b=>b.onclick=()=>{localStorage.setItem('tv_sales_focus',JSON.stringify({type:'query',name:q,query:q,id:b.dataset.id}));close();if(profile.role==='backoffice'){localStorage.setItem('tv_bo_search',q);navigate('backoffice')}else navigate(profile.role==='consultant'?'my-sales':'team')})}catch(err){results.innerHTML=`<div class="empty">${escapeHtml(err.message)}</div>`}},260)} }


async function renderSystemHealthV40(hours=24){setTitle('Saúde do sistema','Erros, estabilidade e versões em uso');const {data,error}=await sb.rpc('tv_system_health',{p_hours:hours});if(error)throw error;const d=data||{},recent=d.recent||[],versions=d.versions||[];content.innerHTML=`<div class="health-toolbar card"><div><div class="kicker">OBSERVABILIDADE</div><h2>Saúde do TechNET Vendas</h2><p class="muted">Eventos técnicos sem conteúdo de formulários ou dados sensíveis do cliente.</p></div><div><button class="ghost health-range ${hours===24?'active':''}" data-h="24">24 horas</button><button class="ghost health-range ${hours===168?'active':''}" data-h="168">7 dias</button></div></div><div class="stats health-stats"><div class="stat"><div class="label">Eventos</div><div class="value">${Number(d.total_events||0)}</div><div class="sub">No período</div></div><div class="stat"><div class="label">Erros</div><div class="value">${Number(d.errors||0)}</div><div class="sub">Erro + fatal</div></div><div class="stat"><div class="label">Críticos</div><div class="value">${Number(d.fatal||0)}</div><div class="sub">Falhas fatais</div></div><div class="stat"><div class="label">Usuários</div><div class="value">${Number(d.users||0)}</div><div class="sub">Com telemetria</div></div></div><div class="grid2"><article class="card"><div class="card-head"><div><h3>Versões em uso</h3><span class="muted">Adoção e erros por versão</span></div></div><div class="health-versions">${versions.length?versions.map(v=>`<div><span><b>v${escapeHtml(v.app_version)}</b><small>Último sinal ${technicalDate(v.last_seen)}</small></span><span><b>${Number(v.events||0)}</b><small>eventos</small></span><span class="${Number(v.errors||0)?'bad':'good'}"><b>${Number(v.errors||0)}</b><small>erros</small></span></div>`).join(''):'<div class="empty">Ainda sem telemetria suficiente.</div>'}</div></article><article class="card"><div class="card-head"><div><h3>Últimos eventos</h3><span class="muted">Até 50 registros técnicos recentes</span></div></div><div class="health-events">${recent.length?recent.map(e=>`<div class="health-event ${escapeHtml(e.severity||'info')}"><i></i><span><b>${escapeHtml(e.event_type||'evento')}</b><small>${escapeHtml(e.page||'')} · ${technicalDate(e.created_at)}</small><p>${escapeHtml(e.message||'')}</p></span><em>v${escapeHtml(e.app_version||'?')}</em></div>`).join(''):'<div class="empty">Nenhum evento no período.</div>'}</div></article></div>`;document.querySelectorAll('.health-range').forEach(b=>b.onclick=()=>renderSystemHealthV40(Number(b.dataset.h)))}

function setupAndroidUXV41(){if(window.__tvAndroidUXV41)return;window.__tvAndroidUXV41=true;const vv=window.visualViewport;const isEditor=()=>{const e=document.activeElement;return !!e&&['INPUT','TEXTAREA','SELECT'].includes(e.tagName)};const update=()=>{const short=vv?vv.height<window.innerHeight*.78:false,hidden=isEditor()&&short,changed=document.body.classList.contains('keyboard-open')!==hidden;document.body.classList.toggle('keyboard-open',hidden);if(changed)setMobileBottomNavKeyboardHidden(hidden)};document.addEventListener('focusin',e=>{setTimeout(()=>{update();if(window.innerWidth<=820&&e.target?.scrollIntoView)e.target.scrollIntoView({block:document.body.classList.contains('login-active')?'nearest':'center',behavior:window.matchMedia('(prefers-reduced-motion:reduce)').matches?'auto':'smooth'})},220)});document.addEventListener('focusout',()=>setTimeout(update,220));vv?.addEventListener('resize',update);vv?.addEventListener('scroll',update);window.addEventListener('orientationchange',()=>setTimeout(update,350));update()}
function setupConnectivityV37(){let b=document.getElementById('connectivityBadge');if(!b){b=document.createElement('span');b.id='connectivityBadge';b.className='connectivity-badge';document.querySelector('.top-actions')?.prepend(b)}const draw=()=>{const on=navigator.onLine;b.textContent=on?'● Online':'● Offline';b.classList.toggle('offline',!on)};window.addEventListener('online',draw);window.addEventListener('offline',draw);draw()}
function showUpdateBannerV37(){if(document.getElementById('updateBanner'))return;const b=document.createElement('div');b.id='updateBanner';b.className='update-banner';b.innerHTML=`<div><b>Nova versão disponível</b><span>Atualize para usar as melhorias mais recentes.</span></div><button class="primary" id="applyUpdate">Atualizar agora</button><button class="ghost" id="dismissUpdate" aria-label="Fechar">${icon('close')}</button>`;document.body.appendChild(b);document.getElementById('applyUpdate').onclick=()=>location.reload();document.getElementById('dismissUpdate').onclick=()=>b.remove()}
if('serviceWorker' in navigator)window.addEventListener('load',async()=>{try{const reg=await navigator.serviceWorker.register('/sw-v48.js?v=127');reg.addEventListener('updatefound',()=>{const w=reg.installing;if(!w)return;w.addEventListener('statechange',()=>{if(w.state==='installed'&&navigator.serviceWorker.controller)showUpdateBannerV37()})});setInterval(()=>reg.update().catch(()=>{}),30*60*1000)}catch(e){console.warn('service worker',e)}});

function setupPremiumTilt(root=document){if(!window.matchMedia('(hover:hover) and (pointer:fine)').matches||window.matchMedia('(prefers-reduced-motion:reduce)').matches)return;root.querySelectorAll('[data-tilt-card],.login-card-wrap').forEach(card=>{if(card.dataset.tiltReady)return;card.dataset.tiltReady='true';let frame=0;const reset=()=>{cancelAnimationFrame(frame);card.style.setProperty('--tilt-x','0deg');card.style.setProperty('--tilt-y','0deg');card.style.setProperty('--light-x','50%');card.style.setProperty('--light-y','50%')};card.addEventListener('pointermove',e=>{const r=card.getBoundingClientRect(),x=(e.clientX-r.left)/r.width,y=(e.clientY-r.top)/r.height;cancelAnimationFrame(frame);frame=requestAnimationFrame(()=>{card.style.setProperty('--tilt-x',`${(0.5-y)*8}deg`);card.style.setProperty('--tilt-y',`${(x-0.5)*10}deg`);card.style.setProperty('--light-x',`${x*100}%`);card.style.setProperty('--light-y',`${y*100}%`)})},{passive:true});card.addEventListener('pointerleave',reset)})}
function setupPremiumMotion(root=document){if(window.matchMedia('(prefers-reduced-motion:reduce)').matches)return;root.classList.add('premium-motion-ready');root.querySelectorAll('[data-count]').forEach(el=>{const target=Number(el.dataset.count||0),started=performance.now(),duration=950;el.textContent='0';const tick=now=>{const p=Math.min(1,(now-started)/duration),ease=1-Math.pow(1-p,4);el.textContent=String(Math.round(target*ease));if(p<1)requestAnimationFrame(tick)};requestAnimationFrame(tick)})}
window.TechNETDashboardMotion={setupMotion:setupPremiumMotion,setupTilt:setupPremiumTilt};
window.addEventListener('DOMContentLoaded',()=>{mountClaroBubblesBackground();setupAndroidUXV41();const b=localStorage.getItem('tv_imp_base'),u=localStorage.getItem('tv_imp_user');if(b&&document.getElementById('impBase'))document.getElementById('impBase').value=b;if(u&&document.getElementById('impUser'))document.getElementById('impUser').value=u;setupPremiumTilt(document.getElementById('loginView')||document)});


